heuristic.toad_enforcement:

// FALSCH (AI-SLOP):
circle #ambientGlow { at: center; size: 800px; fill: radial(#8B5CF6, transparent); blur: 120px; }

// RICHTIG (PROFESSIONELLES LICHT):
rect #card {
  fill: #131722;
  border: 1px solid alpha(#FFFFFF, 0.08);
  shadow: 0 20px 40px alpha(#000000, 0.4);
}


// FALSCH (KI-SLOP GLAS-OVERDOSE):
rect #slopCard {
  fill: alpha(#FFFFFF, 0.05);
  border: 1px solid alpha(#FFFFFF, 0.15);
  radius: 32px;
  blur: 20px;
}

// RICHTIG (PROFESSIONELLES, OPAKES DESIGN):
rect #solidCard {
  fill: #1E293B;
  border: 1px solid #334155;
  radius: 8px;
  shadow: 0 4px 12px alpha(#000000, 0.08);
}


// FALSCH (KI-SLOP HORROR VACUI: ALLES VOLLGESTOPFT):
stack #clutteredHero {
  badge #b1 { text "AI Powered" {} }
  badge #b2 { text "Next-Gen" {} }
  badge #b3 { text "Zero Latency" {} }
  text #h1 { "Supercharge Everything" {} }
  text #sub { "Lorem ipsum dolor sit amet..." {} }
  rect #stat1 { text "99.9% Uptime" {} }
  rect #stat2 { text "10x Speed" {} }
  rect #stat3 { text "Zero Cost" {} }
  // 15 weitere Mini-Cards...
}

// RICHTIG (SOUVERÄNE REDUKTION & WEISSRAUM):
stack #calmHero {
  gap: 32px;
  text #headline {
    size: 64px;
    font-weight: 800;
    "Cloud-ERP ohne bürokratischen Ballast."
  }
  text #sub {
    size: 20px;
    color: #64748B;
    width: 600px;
    "Automatische Buchhaltung und Lagerverwaltung für den Mittelstand."
  }
  rect #ctaButton {
    fill: #6D213F;
    radius: 9999px;
    padding: 16px 36px;
    text "Kostenlos testen" { color: #FFFFFF; font-weight: 600; }
  }
}
